'use client';

import { useRooms } from '@/hooks/useRooms';
import { useSession } from '@/hooks/useSession';
import { useRouter, useParams } from 'next/navigation';
import { Icons } from '@/components/icons';

export default function RoomSidebar() {
    const { rooms, loading: roomsLoading, error } = useRooms();
    const { user } = useSession();
    const router = useRouter();
    const params = useParams();
    const currentRoomId = params?.roomId as string;

    const handleCreateRoom = () => {
        router.push('/rooms'); // Navigate to index/create page
    };

    return (
        <aside className="w-72 bg-surface-base dark:bg-surface-darkElevated border-r border-border-default dark:border-border-darkDefault flex flex-col h-full">
            {/* Header */}
            <div className="px-4 py-4 flex items-center justify-between shrink-0">
                <h2 className="font-semibold text-text-primary dark:text-text-darkPrimary flex items-center gap-2">
                    <Icons.Hash className="w-4 h-4 text-brand-primary dark:text-brand-primaryDark" /> Rooms
                </h2>
                <button
                    onClick={handleCreateRoom}
                    className="w-8 h-8 rounded-full bg-surface-subtle dark:bg-surface-darkSubtle text-brand-primary dark:text-brand-primaryDark hover:bg-brand-muted dark:hover:bg-brand-mutedDark transition flex items-center justify-center p-1"
                >
                    <Icons.Plus className="w-5 h-5" />
                </button>
            </div>

            {/* Room List */}
            <div className="flex-1 px-3 space-y-2 overflow-y-auto">
                {roomsLoading && <p className="text-center text-xs text-text-muted dark:text-text-darkMuted mt-4">Loading rooms...</p>}
                {error && <p className="text-center text-xs text-status-danger dark:text-status-dangerDark mt-4">Error loading rooms</p>}

                {!roomsLoading && rooms.map(room => (
                    <RoomItem
                        key={room.$id}
                        name={room.name}
                        status={room.status}
                        active={room.$id === currentRoomId}
                        onClick={() => router.push(`/room/${room.$id}`)}
                    />
                ))}

                {!roomsLoading && rooms.length === 0 && (
                    <div className="text-center py-8">
                        <p className="text-sm text-text-secondary dark:text-text-darkSecondary">No public rooms yet.</p>
                    </div>
                )}
            </div>

            {/* User */}
            <div className="border-t border-border-default dark:border-border-darkDefault p-4 flex items-center gap-3 shrink-0 bg-surface-subtle dark:bg-surface-darkSubtle">
                <div className="w-9 h-9 rounded-full bg-brand-muted/50 dark:bg-brand-mutedDark/50 flex items-center justify-center text-brand-primary dark:text-brand-primaryDark text-xs font-bold">
                    {user?.username ? user.username.charAt(0).toUpperCase() : '?'}
                </div>
                <div className="min-w-0">
                    <p className="text-sm font-medium truncate text-text-primary dark:text-text-darkPrimary">{user?.username || 'Guest'}</p>
                    <p className="text-xs text-status-success dark:text-status-successDark flex items-center gap-1">
                        <span className="w-1.5 h-1.5 rounded-full bg-status-success dark:bg-status-successDark"></span>
                        Online
                    </p>
                </div>
            </div>
        </aside>
    );
}

function RoomItem({
    name,
    status,
    active,
    onClick
}: {
    name: string;
    status: string;
    active?: boolean;
    onClick?: () => void;
}) {
    return (
        <div
            onClick={onClick}
            className={`px-4 py-3 rounded-xl cursor-pointer transition flex items-center gap-3 ${active
                ? "bg-brand-primary dark:bg-brand-primaryDark text-text-inverse shadow-md"
                : "hover:bg-surface-subtle dark:hover:bg-surface-darkSubtle text-text-secondary dark:text-text-darkSecondary"
                }`}
        >
            <Icons.Hash className={`w-4 h-4 shrink-0 ${active ? "text-white" : "text-gray-400 dark:text-gray-500"}`} />
            <div className="min-w-0">
                <p className="font-medium truncate">{name}</p>
                <p className={`text-xs ${active ? "opacity-90" : "opacity-60"}`}>{status}</p>
            </div>
        </div>
    );
}
